        /**
         * Only if `mode`!=`dynamic`. When enabled, the port is not expected to receive BPDU frames
         */
        stpEdge?: boolean;
        /**
         * Only if `mode`!=`dynamic`
         */
        stpNoRootPort?: boolean;
        /**
         * Only if `mode`!=`dynamic`
         */
        stpP2p?: boolean;
        /**
         * Only if `mode`!=`dynamic`. Whether to remain in block state if no BPDU is received
         */
