        /**
         * Only if `mode`!=`dynamic`. If dot1x is desired, set to dot1x. enum: `dot1x`
         */
        portAuth?: string;
        /**
         * Only if `mode`!=`dynamic`. Native network/vlan for untagged traffic
         */
